/**
 * Ambient HTTP request context for code running outside a controller's scope.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 *
 * A controller handler receives the request through `@Req()`. A service
 * function (`functions.ts`), a lifecycle hook and an entity method do not, yet
 * they run on a handler's call path and may read the request through the
 * `Request.*` DSL accessors and the caller through the `Auth.*` ones. This module binds the active request in an
 * `AsyncLocalStorage` for the whole async call path of each HTTP request, so
 * those accessors resolve anywhere on that path. A `Request.*` accessor fails
 * loud on any path that has no request (a job, a queue worker, startup), where
 * a request-scoped value has no meaning. The caller accessors (`currentUser*`)
 * answer an absent principal explicitly instead: the id is `null`, the role
 * check is `false`, and every other read raises -- never a fabricated value.
 *
 * `requestContextMiddleware` is installed by `main.ts` before any other
 * middleware, guard, or handler runs; the guards that later attach the
 * verified principal to `request.user` mutate the same object this store holds.
 */
import { AsyncLocalStorage } from 'node:async_hooks';
import { UnauthorizedException } from '@nestjs/common';
import type { NextFunction, Request, Response } from 'express';
import { bearerTokenOrForbidden } from '../auth/auth-chain';
import type { IdentityPrincipal } from '../auth/identity';

/** The request after `TenantGuard` attached the tenant it resolved and validated. */
type TenantCarrier = Request & { tenantId?: string };

const _requestStore = new AsyncLocalStorage<Request>();

/** Express middleware binding the active request for its whole async call path. */
export function requestContextMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction,
): void {
  _requestStore.run(req, next);
}

/**
 * The HTTP request being served on this call path, or `undefined` when none is
 * active (a job, a queue worker, startup). Non-throwing: for the accessors
 * whose contract is "absent outside a request".
 */
function activeRequest(): Request | undefined {
  return _requestStore.getStore();
}

/**
 * The HTTP request being served on this call path.
 *
 * @throws Error when no HTTP request is active -- the caller is a job, a queue
 *   worker, or startup code, where request context does not exist.
 */
export function currentRequest(): Request {
  const request = activeRequest();
  if (request === undefined) {
    throw new Error(
      'No active HTTP request: a Request.* accessor was evaluated outside an HTTP ' +
        'request (a job, a queue worker, or startup). Request context exists only on ' +
        'the call path of a controller handler; pass the value in as a parameter ' +
        'when the function must also run elsewhere.',
    );
  }
  return request;
}

const UNAUTHENTICATED_PROBLEM = { type: 'about:blank', title: 'Unauthorized', status: 401 } as const;

/** The verified principal `AuthGuard` attached to the active request, or `undefined`. */
function activePrincipal(): IdentityPrincipal | undefined {
  return activeRequest()?.user;
}

/**
 * The principal an `Auth.<member>` read requires.
 *
 * @throws Error when no HTTP request is active (a lifecycle hook, service function or
 *   entity method run by a job, a queue worker or startup), naming the member.
 * @throws UnauthorizedException when a request is active but anonymous (an optional
 *   route served without a credential) -- the opaque 401 problem `AuthGuard` throws.
 */
function requirePrincipal(member: string): IdentityPrincipal {
  const request = activeRequest();
  if (request === undefined) {
    throw new Error(
      `Auth.${member} was read outside an authenticated HTTP request (a lifecycle hook, ` +
        'service function or entity method run by a job, a queue worker or startup). Pass ' +
        'the value in as a parameter when the code must also run there.',
    );
  }
  const principal = request.user;
  if (principal === undefined) {
    throw new UnauthorizedException(UNAUTHENTICATED_PROBLEM);
  }
  return principal;
}

/**
 * Resolved local id of the authenticated principal (never the raw provider
 * `sub`), typed via the global `Express.Request` augmentation in identity.ts --
 * no `any` cast. `null` on an anonymous request and outside a request.
 */
export function currentUserId(): string | null {
  return activePrincipal()?.userId ?? null;
}

/** The principal with `id` aliased to its resolved `userId` (what `Auth.user()` reads). */
export function currentUser(): IdentityPrincipal & { readonly id: string } {
  const principal = requirePrincipal('user');
  return { ...principal, id: principal.userId };
}

/**
 * The bearer token the principal was authenticated with (the `Auth` token read).
 *
 * @throws ForbiddenException when the principal carries no forwardable credential
 *   (an API-key principal): the raw key is never forwarded downstream.
 */
export function currentUserToken(): string {
  return bearerTokenOrForbidden(requirePrincipal('token'));
}

/** The raw provider subject of the principal (what `Auth.subject` reads). */
export function currentUserSubject(): IdentityPrincipal['subject'] {
  return requirePrincipal('subject').subject;
}

/** The projected local profile of the principal (what `Auth.profile` reads). */
export function currentUserProfile(): IdentityPrincipal['profile'] {
  return requirePrincipal('profile').profile;
}

/** The verified claims of the principal (what `Auth.identity.<claim>` reads). */
export function currentUserIdentity(): IdentityPrincipal['identity'] {
  return requirePrincipal('identity').identity;
}

/** `false` without a principal: no principal grants nothing. */
export function currentUserHasRole(role: string): boolean {
  return activePrincipal()?.roles.includes(role) ?? false;
}

/**
 * Tenant of the request being served: the value `TenantGuard` resolved from
 * the configured tenant source and validated -- never a client-writable
 * principal claim read around the guard.
 *
 * Fails closed: every query over a tenant-scoped entity is filtered by this
 * value, so a request that reached a handler with no tenant bound (relaxed
 * enforcement, a missing identifier) is rejected here rather than querying
 * with an absent tenant.
 *
 * @throws UnauthorizedException when the request carries no resolved tenant.
 */
export function currentTenantId(): string {
  const tenantId = (currentRequest() as TenantCarrier).tenantId;
  if (tenantId === undefined || tenantId === '') {
    throw new UnauthorizedException('Missing required tenant identifier');
  }
  return tenantId;
}

/** Remote address of the active request; empty when the transport reports none. */
export function currentClientIp(): string {
  return currentRequest().ip ?? '';
}
